package sample
var Events []string
func WorkDefer() {
 defer func() { Events = append(Events,"defer") }()
 Events = append(Events,"selected")
 Events = append(Events,"after")
}
func WorkRecover() any {
 var recovered any
 func() {
  defer func() {
   recovered = recover()
   Events = append(Events,"recovered")
  }()
  panic("marker")
 }()
 return recovered
}

